'use strict';

// MAIN //

var defaults = {
	// Recursion cutoff: the conventional algorithm is used once any subproblem dimension is less than or equal to this value (NOTE: the value was chosen empirically, by benchmarking the Strassen–Winograd algorithm for a range of cutoffs and problem sizes):
	'CUTOFF': 64|0,

	// Maximum number of recursion levels (NOTE: IBM ESSL's `DGEMMS` likewise caps the Winograd variant at four levels, bounding the growth of the normwise error constant, which increases by a factor of approximately 4.5 per level):
	'LEVELS': 4|0
};


// EXPORTS //

module.exports = defaults;
